[ExecuteAlways]public sealed class Walk257View:MonoBehaviour{
 public Palette256View source;public TextAsset phaseInputs;public Mesh backingHeadLocal;public Eye253R3View.SourceState[]preservedStates;public int phaseIndex=8;public bool playing;public float speed=1;
 Walk257Inputs inputs;int last=-1;float elapsed;Mesh face,backing,registered,other;Eye253R3View.SourceState live;
