 public void Apply(){if(!source||!phaseInputs||!backingHeadLocal)return;inputs??=JsonUtility.FromJson<Walk257Inputs>(phaseInputs.text);if(inputs.frames.Count!=16)return;phaseIndex=Mathf.Clamp(phaseIndex,0,15);if(last!=phaseIndex||!face){DestroyScratch();var data=inputs.frames[phaseIndex];var body=Body;body.poseIndex=phaseIndex;body.Apply();var fm=body.renderers[1].GetComponent<MeshFilter>().sharedMesh;var hm=body.renderers[2].GetComponent<MeshFilter>().sharedMesh;face=Face(fm,body.renderers[1].transform.localToWorldMatrix,data);backing=World(backingHeadLocal,data.backingToWorld,new[]{backingHeadLocal.GetIndices(0)},"A257 currentexistingheadskinbacking");var ids=hm.GetIndices(0);registered=World(hm,body.renderers[2].transform.localToWorldMatrix,new[]{ids.Skip(574*3).Take(284*3).ToArray()},"A257 currentregistered284");other=World(hm,body.renderers[2].transform.localToWorldMatrix,new[]{ids.Take(574*3).Concat(ids.Skip(858*3)).ToArray(),hm.GetIndices(1),hm.GetIndices(2),hm.GetIndices(3)},"A257 currentotherhair");live=new Eye253R3View.SourceState{tag="WALK"+phaseIndex,poseIndex=phaseIndex,blinkWeight=0,head=data.head,anchors=data.anchors,face=face,backing=backing,registered=registered,other=other};last=phaseIndex;}Eye.states=new[]{live};Eye.stateIndex=0;source.Apply();}
 static Mesh World(Mesh src,Matrix4x4 matrix,int[][]groups,string name){var p=src.vertices;var n=src.normals;var normal=matrix.inverse.transpose;for(int i=0;i<p.Length;i++){p[i]=matrix.MultiplyPoint3x4(p[i]);n[i]=normal.MultiplyVector(n[i]).normalized;}var m=new Mesh{name=name,indexFormat=src.indexFormat,hideFlags=HideFlags.DontSave};m.vertices=p;m.normals=n;m.uv=src.uv;var ctrl=new List<Vector4>();var own=new List<Vector2>();src.GetUVs(2,ctrl);src.GetUVs(7,own);if(ctrl.Count==p.Length)m.SetUVs(2,ctrl);if(own.Count==p.Length)m.SetUVs(7,own);m.subMeshCount=groups.Length;for(int i=0;i<groups.Length;i++)m.SetIndices(groups[i],MeshTopology.Triangles,i,false);m.RecalculateBounds();return m;}
 static Mesh Face(Mesh src,Matrix4x4 matrix,Walk257Frame s){var vp=src.vertices;var vn=src.normals;var uv=src.uv;var ctrl=new List<Vector4>();var own=new List<Vector2>();src.GetUVs(2,ctrl);src.GetUVs(7,own);if(ctrl.Count!=vp.Length||own.Count!=vp.Length)throw new Exception("A257 cachedface lacks originalcontrol/owner UV");var p=new List<Vector3>();var n=new List<Vector3>();var u=new List<Vector2>();var c=new List<Vector4>();var o=new List<Vector2>();var groups=new List<int[]>();var normal=matrix.inverse.transpose;
  for(int sm=0;sm<src.subMeshCount;sm++){var ids=src.GetIndices(sm);int start=p.Count;var provider=s.providers[sm];foreach(int i in ids){Vector3 w=matrix.MultiplyPoint3x4(vp[i])+s.sourceOrigin;Vector4 control=ctrl[i];
   if(provider.eyeEnabled>.5&&(provider.role==1||provider.role==2||provider.role==4||provider.role==6)){bool ocular=provider.role==1||provider.role==2;Vector3 a0=ocular?provider.eyeAnchor0:provider.headAnchor0,a1=ocular?provider.eyeAnchor1:provider.headAnchor1;bool right=(w-a0).sqrMagnitude<(w-a1).sqrMagnitude;var anchor=right?a0:a1;float scale=ocular?(right?provider.scales.x:provider.scales.y):(provider.role==4?provider.scales.z:provider.scales.w);w=anchor+(w-anchor)*scale;}
   if(provider.apertureEnabled>.5&&(provider.role==3||provider.role==6)){var hp=provider.toHead.MultiplyPoint3x4(w);bool right=control.x>=control.y;float weight=right?control.x:control.y;Vector3 centre=right?provider.centre0:provider.centre1;hp.x+=(hp.x-centre.x)*(provider.apertureScale.x-1)*weight;hp.y+=(hp.y-centre.y)*(provider.apertureScale.y-1)*weight;w=provider.toWorld.MultiplyPoint3x4(hp);}
   p.Add(w-s.sourceOrigin);n.Add(normal.MultiplyVector(vn[i]).normalized);u.Add(uv[i]);c.Add(control);o.Add(own[i]);}groups.Add(Enumerable.Range(start,ids.Length).ToArray());}
  var m=new Mesh{name="A257 existingcurrentproviderface",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32,hideFlags=HideFlags.DontSave};m.SetVertices(p);m.SetNormals(n);m.SetUVs(0,u);m.SetUVs(2,c);m.SetUVs(7,o);m.subMeshCount=groups.Count;for(int i=0;i<groups.Count;i++)m.SetTriangles(groups[i],i,false);m.RecalculateBounds();return m;}
 void OnGUI(){GUI.Box(new Rect(12,12,360,82),"A257 existing16phase actual walk / technical candidate");if(GUI.Button(new Rect(22,40,75,25),playing?"Pause":"Play"))playing=!playing;if(GUI.Button(new Rect(102,40,50,25),"<")){playing=false;phaseIndex=(phaseIndex+15)%16;}if(GUI.Button(new Rect(157,40,50,25),">")){playing=false;phaseIndex=(phaseIndex+1)%16;}GUI.Label(new Rect(215,42,150,25),"Phase "+phaseIndex+" / speed "+speed.ToString("0.00"));speed=GUI.HorizontalSlider(new Rect(22,75,330,15),speed,.15f,1.5f);}
